'use strict';
// Built-ins only, so local modules are checked before their first evaluation.
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const hash=b=>crypto.createHash('sha256').update(b).digest('hex');
function fail(){throw Error('PROTECTED_BOOTSTRAP_REFUSED');}
function read(p,max){const l=fs.lstatSync(p),real=fs.realpathSync.native(p);if(!l.isFile()||l.isSymbolicLink()||l.nlink!==1||l.size<1||l.size>max||path.resolve(p)!==real)fail();const fd=fs.openSync(p,fs.constants.O_RDONLY);try{const cmp=x=>['dev','ino','nlink','mode','size','mtimeMs','ctimeMs'].every(k=>x[k]===l[k]);if(!cmp(fs.fstatSync(fd)))fail();const b=Buffer.alloc(l.size);let n=0;while(n<b.length){const c=fs.readSync(fd,b,n,b.length-n,n);if(c<1)fail();n+=c;}if(fs.readSync(fd,Buffer.alloc(1),0,1,n)!==0||!cmp(fs.fstatSync(fd))||!cmp(fs.lstatSync(p))||fs.realpathSync.native(p)!==real)fail();return b;}finally{fs.closeSync(fd);}}
function hold(root,expected){if(!/^[0-9a-f]{64}$/.test(expected))fail();const raw=read(path.join(root,'source-review.json'),2000000);if(hash(raw)!==expected)fail();const v=JSON.parse(raw);if(v.kind!=='ROOT_PROTECTED_IOS18_SOURCE_REVIEW'||!Array.isArray(v.files)||v.files.length<1)fail();const rows=[],seen=new Set();for(const r of v.files){if(!r||Object.keys(r).sort().join(',')!=='bytes,file,sha256'||!/^[A-Za-z0-9_.-]+$/.test(r.file)||seen.has(r.file)||!Number.isSafeInteger(r.bytes)||r.bytes<1||!(/^[0-9a-f]{64}$/).test(r.sha256))fail();seen.add(r.file);rows.push({...r,file:path.join(root,r.file)});}const check=()=>{if(hash(read(path.join(root,'source-review.json'),2000000))!==expected)fail();for(const r of rows){const b=read(r.file,r.bytes);if(b.length!==r.bytes||hash(b)!==r.sha256)fail();}};check();return{v,rows,check};}
module.exports={hash,read,hold};
